package com.curso.cotacao;
import com.curso.config.CotacaoProperties;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import java.util.List;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component public class BrapiCatalogoClient{private final RestClient client;public BrapiCatalogoClient(RestClient.Builder b,CotacaoProperties p){client=b.baseUrl(p.brapi().baseUrl()).build();}public List<String> buscar(){try{Resposta r=client.get().uri("/api/available").retrieve().body(Resposta.class);if(r==null||r.stocks()==null)throw new RestClientException("Resposta inválida");return r.stocks();}catch(RestClientException e){throw e;}}@JsonIgnoreProperties(ignoreUnknown=true)public record Resposta(List<String> stocks,List<String> indexes){}}
